{
  "findings": [
    {
      "check_id": "CKV_AWS_144",
      "title": "CloudWatch Log Group not encrypted",
      "resource": "aws_cloudwatch_log_group.CIS_CloudWatch_LogsGroup",
      "severity": "HIGH",
      "explanation": "The CloudWatch Log Group referenced in the log metric filter is not defined in this file, and there is no indication that it is encrypted. Unencrypted log groups can expose sensitive data if accessed by unauthorized users."
    },
    {
      "check_id": "CKV_AWS_125",
      "title": "SNS Topic not encrypted",
      "resource": "aws_sns_topic.CIS_Alerts_SNS_Topic",
      "severity": "HIGH",
      "explanation": "The SNS Topic used for alarm actions is not defined in this file, and there is no indication that it is encrypted. Unencrypted SNS Topics can expose sensitive data in transit or at rest."
    }
  ],
  "patched_code": "resource "aws_cloudwatch_log_metric_filter" "CIS_AWS_Config_Change_Metric_Filter" {
  name           = "CIS-AWSConfigChanges"
  pattern        = "{ ($.eventSource = \"config.amazonaws.com\") && (($.eventName=StopConfigurationRecorder)||($.eventName=DeleteDeliveryChannel)||($.eventName=PutDeliveryChannel)||($.eventName=PutConfigurationRecorder)) }"
  log_group_name = aws_cloudwatch_log_group.CIS_CloudWatch_LogsGroup.name

  metric_transformation {
    name      = "CIS-AWSConfigChanges"
    namespace = "CIS_Metric_Alarm_Namespace"
    value     = "1"
  }
}
resource "aws_cloudwatch_metric_alarm" "CIS_AWS_Config_Change_CW_Alarm" {
  alarm_name                = "CIS-3.9-AWSConfigChanges"
  comparison_operator       = "GreaterThanOrEqualToThreshold"
  evaluation_periods        = "1"
  metric_name               = aws_cloudwatch_log_metric_filter.CIS_AWS_Config_Change_Metric_Filter.id
  namespace                 = "CIS_Metric_Alarm_Namespace"
  period                    = "300"
  statistic                 = "Sum"
  threshold                 = "1"
  alarm_description         = "Monitoring changes to AWS Config configuration will help ensure sustained visibility of configuration items within the AWS account."
  alarm_actions             = [aws_sns_topic.CIS_Alerts_SNS_Topic.arn]
  insufficient_data_actions = []
}

resource "aws_cloudwatch_log_group" "CIS_CloudWatch_LogsGroup" {
  name              = "CIS_CloudWatch_LogsGroup"
  retention_in_days = 90
  kms_key_id        = aws_kms_key.cloudwatch_logs_key.arn
}

resource "aws_kms_key" "cloudwatch_logs_key" {
  description             = "KMS key for encrypting CloudWatch Logs"
  enable_key_rotation     = true
}

resource "aws_sns_topic" "CIS_Alerts_SNS_Topic" {
  name              = "CIS_Alerts_SNS_Topic"
  kms_master_key_id = aws_kms_key.sns_topic_key.arn
}

resource "aws_kms_key" "sns_topic_key" {
  description             = "KMS key for encrypting SNS Topic"
  enable_key_rotation     = true
}",
  "fix_summary": "Added encryption for the CloudWatch Log Group and SNS Topic by defining KMS keys and associating them with the respective resources."
}
